class Solution {
    public int numIdenticalPairs(int[] nums) {
        int pairs = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] == nums[j]) {
                    pairs++;
                }
            }
        }
        return pairs;
    }
}

class Solution {
    public int numIdenticalPairs(int[] nums) {
        int[] frequency = new int[101];
        int pairs = 0;
        for (int value : nums) {
            pairs += frequency[value];
            frequency[value]++;
        }
        return pairs;
    }
}

class Solution {
    public int numIdenticalPairs(int[] nums) {
        int[] frequency = new int[101];
        for (int value : nums) {
            frequency[value]++;
        }

        int pairs = 0;
        for (int count : frequency) {
            pairs += count * (count - 1) / 2;
        }
        return pairs;
    }
}

import java.util.Arrays;

class Solution {
    public int numIdenticalPairs(int[] nums) {
        Arrays.sort(nums);
        int pairs = 0;
        int runLength = 1;

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] == nums[i - 1]) {
                runLength++;
            } else {
                pairs += runLength * (runLength - 1) / 2;
                runLength = 1;
            }
        }
        pairs += runLength * (runLength - 1) / 2;
        return pairs;
    }
}
